    title: []const u8,
    /// The HTTP status code generated by the origin server.
    /// This is advisory; the actual HTTP status code takes precedence.
    status: u16,
    /// A human-readable explanation specific to this occurrence of the problem.
    detail: ?[]const u8,
    /// A URI reference that identifies the specific occurrence of the problem.
    /// It may or may not yield further information if dereferenced.
    instance: ?[]const u8,
    /// Extension members - problem-type-specific data.
    /// For validation errors, this typically contains an "errors" array.
    extensions: std.StringHashMap([]const u8),
};

/// A single channel extracted from an AsyncAPI spec
pub const ParsedChannel = struct {
    /// Channel key from the spec (e.g. "chat/messages")
    name: []const u8,
    /// Channel address / path
    address: []const u8,
    /// Message names declared on this channel
    messages: []const []const u8,
    /// Bindings (ws / http / amqp / …) as raw JSON for forward-compatibility
    bindings: ?[]const u8,
};

/// A single operation extracted from an AsyncAPI spec
pub const ParsedOperation = struct {
    /// Operation name
    name: []const u8,
    /// Operation action: "send" or "receive"
    action: []const u8,
    /// Channel reference (resolved to the channel name)
    channel: []const u8,
};

/// A resolved message (name + JSON Schema)
pub const ParsedMessage = struct {
    /// Message name
    name: []const u8,
    /// Resolved JSON Schema for the message payload, if available
    schema: ?[]const u8,
};

/// Full parse result returned by `POST /asyncapi/parse`
pub const ParseResult = struct {
    spec_version: []const u8,
    title: []const u8,
    api_version: []const u8,
    channels: []const ParsedChannel,
    operations: []const ParsedOperation,
    messages: []const ParsedMessage,
};

/// Contact information
pub const ContactInfo = struct {
