    }
};

pub const RequestData = struct {
    _handle: ?*anyopaque,

    /// Release the underlying FFI handle. Safe to call more than once.
    pub fn free(self: *RequestData) void {
        const handle = self._handle orelse return;
        self._handle = null;
        c.spikard_request_data_free(@as(*c.SPIKARDRequestData, @ptrCast(handle)));
    }
};
